import{_ as a,o as t,c as i,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const u=JSON.parse('{"title":"CreateNotenHeader","description":"","frontmatter":{"title":"CreateNotenHeader","source_pageid":23,"source_revision":314},"headers":[],"relativePath":"reporting/rap/createnotenheader.md","filePath":"reporting/rap/createnotenheader.md"}'),s={name:"reporting/rap/createnotenheader.md"};function n(d,e,h,l,p,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="createnotenheader" tabindex="-1">CreateNotenHeader <a class="header-anchor" href="#createnotenheader" aria-label="Permalink to &quot;CreateNotenHeader&quot;">​</a></h1><h2 id="beschreibung" tabindex="-1">Beschreibung <a class="header-anchor" href="#beschreibung" aria-label="Permalink to &quot;Beschreibung&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">procedure</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CreateNotenHeader</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(aFaecherListe: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Im tatsächlich erzeugten Header stehen die Fächer in der unter „Unterrichtsfächer“ festgelegten Sortierreihenfolge.</p><p>Verwenden Sie die Prozedur für eine gemeinsame tabellarische Übersicht über die ausgewählten Schülerinnen und Schüler und ihre Leistungsdaten. Der Aufruf liest dazu die Leistungsdaten der gesamten Auswahl und stellt die vorkommenden Fächer in einer internen Tabelle zusammen. Für andere Ausgaben ist dieser zusätzliche Aufruf nicht nötig.</p><p><strong>Nach der Darstellung der Tabelle muss unbedingt die Prozedur <code>ResetFaechervorbelegung</code> aufgerufen werden!</strong></p><h2 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>aFaecherListe</code></td><td>Kommaseparierte Liste der Fachkürzel, für die eine Übersicht erzeugt werden soll.</td></tr></tbody></table><h2 id="beispiel" tabindex="-1">Beispiel <a class="header-anchor" href="#beispiel" aria-label="Permalink to &quot;Beispiel&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CreateNotenHeader(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D,E,M,F,L&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Bei den Konferenz-Übersichten (d.h. Vorlagen, die die Datenquellen <code>FachUebersichtHeader</code> und <code>FachUebersicht</code> verwenden) stehen im Befehl <code>CreateNotenHeader</code> weitere Optionen zum Filtern auf Fächer zur Verfügung:</p><p>Es können die Platzhalter <code>*</code> oder <code>%</code> gleichbedeutend verwendet werden. Beispiel:</p><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CreateNotenHeader( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D,M,E*&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><p>Dieser Aufruf würde nur die Fächer D, M und solche, die mit E anfangen, berücksichtigen (also z.B. E5, EK).</p><p>Der Platzhalter <code>#</code> kann speziell für Fremdsprachen mit Jahrgangsangabe verwendet werden. Beispiel:</p><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CreateNotenHeader( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;D,M,E#&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><p>Dieser Aufruf würde nur die Fächer D, M und alle Englisch-Fächer berücksichtigen (aber nicht EK).</p><p><strong>Zurück zu <a href="/reporting/rap.html">RAP-Funktionen</a></strong></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=CreateNotenHeader" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 314.</p>',20)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
